/* no-way-up — 上課的解題小遊戲題庫(統測風格)
 *
 * 2026-08-04 kc:「上課的話可以接解題小遊戲,真的一些統測題目,
 *   答對了可以觸發好學生相關的事件,比如會有獎學金,或是正常打工
 *   出示成績單會比較容易上,然後比較不容易被通緝等等。」
 *
 * 難度:四技二專統測共同科目(國文／英文／數學 B)的中等偏易。
 *   會做的人不會覺得被侮辱,沒讀書的人也答得出幾題。
 *
 * ⚠ 答錯的回饋**絕對不可以嘲笑角色**。責任歸給處境,不是能力——
 *   「不是你笨,是你上完晚班回家已經十一點半」(DESIGN_NOTES 第一天就寫著)。
 *   見 CLAUDE.md 基準線:你站不站在角色那一邊。
 */
(function (root) {

  const BANK = [
    { subj:'數學', q:'一件外套標價 1200 元，先打八折，結帳時再折 100 元。實付多少？',
      opts:['860','960','1000','1100'], a:0,
      note:'1200×0.8 = 960，再減 100 = 860。' },

    { subj:'數學', q:'等差數列首項為 3、公差為 4，第 10 項是多少？',
      opts:['37','39','40','43'], a:1,
      note:'a₁₀ = 3 + (10−1)×4 = 39。' },

    { subj:'數學', q:'時薪 183 元，一天做 6 小時，做 22 天，共領多少？（未扣勞健保）',
      opts:['22,116','23,096','24,156','25,236'], a:2,
      note:'183×6 = 1098，1098×22 = 24,156。' },

    { subj:'英文', q:'She ______ to the convenience store every night after school.',
      opts:['go','goes','going','gone'], a:1,
      note:'主詞第三人稱單數 + 現在簡單式 → goes。' },

    { subj:'英文', q:'I was so tired ______ I fell asleep in the first class.',
      opts:['that','which','what','who'], a:0,
      note:'so ... that ... 句型：如此……以致於……。' },

    { subj:'英文', q:'"Afford" 在句中 "I can\'t afford it." 的意思是：',
      opts:['負擔得起','看得懂','受得了','搬得動'], a:0,
      note:'afford = 負擔得起（費用）。' },

    { subj:'國文', q:'下列「」中的字，讀音正確的是：',
      opts:['「拗」不過他 ㄠˋ','「熨」燙 ㄨㄟˋ','「刨」冰 ㄆㄠˊ','「檔」案 ㄉㄤ'], a:0,
      note:'拗不過 ㄠˋ。熨燙讀 ㄩˋ，刨冰讀 ㄅㄠˋ，檔案讀 ㄉㄤˋ。' },

    { subj:'國文', q:'「捉襟見肘」形容的是：',
      opts:['衣衫不整','窮困而應付不過來','手腳俐落','愛出風頭'], a:1,
      note:'拉一下衣襟就露出手肘，比喻困窘、顧此失彼。' },

    { subj:'國文', q:'「他做事一向<b>因陋就簡</b>」，這個詞的意思是：',
      opts:['將就現有的條件辦事','故意刁難別人','偷工減料騙人','講究排場'], a:0,
      note:'依著簡陋的條件把事情辦成，不一定是貶義。' },

    { subj:'數學', q:'某商品成本 400 元，老闆想賺三成，售價應訂為多少？',
      opts:['430','480','520','570'], a:2,
      note:'400×(1+0.3) = 520。' },

    { subj:'英文', q:'The manager asked me to ______ my transcript.',
      opts:['bring in','bring up','bring out','bring down'], a:0,
      note:'bring in = 帶來、繳交（文件）。transcript 是成績單。' }
  ];

  /* 答對／答錯的回饋。答錯那組:責任歸處境,不歸能力。 */
  const RIGHT = [
    '你算出來了。',
    '這題你會。',
    '筆停了一下，然後你圈了答案。',
    '你想了大概二十秒。'
  ];
  const WRONG = [
    '你看了三遍，字都認得，連起來就是不行。',
    '你昨天到十一點半才回到家。',
    '你知道有教過，你只是想不起來是什麼時候。',
    '你圈了一個，然後把它擦掉，再圈同一個。'
  ];

  root.Quiz = { BANK, RIGHT, WRONG };
})(typeof globalThis !== 'undefined' ? globalThis : this);
